{# SOURCE: https://github.com/churnish/web-clipper-templates #}{# Instagram post or reel. A line that holds only tags prints nothing: a tag swallows the line break after it. In regexes, \x22 stands for a double quote and \x5C for a backslash; never type either one literally inside a regex. #}{% set reel = meta:property:og:url contains "/reel/" %}
{# Display name: og:title up to " on Instagram". #}{% set name = meta:property:og:title|replace:"/ on Instagram.*$/s":""|escape_md %}
{# Caption: the description meta minus its 'N likes, N comments - user on DATE: "' prefix and '".' suffix (no quote anywhere = no caption). Then drop invisible separators, link @mentions and #hashtags, trim line ends, and lead with ":** " to close the bold name; no caption gives just "**". #}{% set caption = meta:name:description|replace:"/^[^\x22]*$/":""|replace:"/^.*?\d\d\d\d. ./s":""|replace:"/.[.] *$/s":""|replace:"/[\u200B\u2060-\u2064\uFEFF]/g":""|replace:"/@([A-Za-z0-9_.]*[A-Za-z0-9_])/g":"[@$1](https://www.instagram.com/$1/)"|replace:"/#([0-9A-Za-z_À-ɏЀ-ӿ]+)/g":"[\\\\#$1](https://www.instagram.com/explore/tags/$1/)"|replace:"/ +$/gm":""|trim|replace:"/^./s":":** $&"|replace:"/^$/":"**" %}
{# Page data: one text per script element, joined unescaped with ¶ (never present in the data). Keep only the first script that holds "candidates": the post's own. Later ones hold other posts. #}{% set post = selector:script[type$=json]|join:"¶"|replace:"/^(.*?[^_]candidates[^¶]*).*$/s":"$1"|replace:"/^.*¶/s":"" %}
{# Full-size link of every media: the first "url" in each "candidates" list. Then drop backslashes, turn u0025 (an escaped percent sign) into %, and drop the repeated cover. #}{% set images = post|replace:"/[^_]candidates[^}]*?url[^a-z]+([^\x22]+)/g":"¶$1¶"|replace:"/\x5C/g":""|replace:"u0025":"%"|split:"¶"|nth:2n|unique %}
{# A reel keeps only its own cover. Any other post gets a label when a "carousel_media" list is followed by media_type 2 (desktop) or a VideoMedia type (mobile). #}{% if reel %}{% set images = images|first %}{% else %}{% set video = post|replace:"/^.*?carousel_media[^a-z0-9_,]*\[.*?(?:media_type\D+2\D|VideoMedia).*$/s":"¶"|replace:"/^[^¶].*$/s":"" %}{% endif %}
**{% if reel %}🩳 {% else %}📢 {% endif %}{{name}}{{caption}}

{% if video %}**Has video**

{% endif %}{{images|image|join:"\n"|replace:"/^!\[\]([^\n]*)$/":"![|392]$1"|replace:"/(.+\n.+)\n/g":"$1\n\n"}}
